package com.bank.rainwater;

import java.math.BigDecimal;
import java.util.logging.Logger;

// Measures trapped reserve between balance peaks for National Bank of India.
public class RainWaterAnalyzer {
    private static final Logger log = Logger.getLogger(RainWaterAnalyzer.class.getName());

    // Total trapped water over the skyline of balances. O(n), O(1).
    public BigDecimal trappedReserve(BigDecimal[] heights) {
        if (heights == null || heights.length < 3) {
            return BigDecimal.ZERO;                 // no dip can hold water
        }
        int left = 0;
        int right = heights.length - 1;
        BigDecimal leftMax = BigDecimal.ZERO;
        BigDecimal rightMax = BigDecimal.ZERO;
        BigDecimal water = BigDecimal.ZERO;
        while (left < right) {
            if (heights[left].compareTo(heights[right]) <= 0) {
                // Left side is the guaranteed-smaller boundary.
                if (heights[left].compareTo(leftMax) >= 0) {
                    leftMax = heights[left];        // new tallest left wall
                } else {
                    water = water.add(leftMax.subtract(heights[left])); // trapped
                }
                left++;
            } else {
                // Right side is the guaranteed-smaller boundary.
                if (heights[right].compareTo(rightMax) >= 0) {
                    rightMax = heights[right];      // new tallest right wall
                } else {
                    water = water.add(rightMax.subtract(heights[right]));
                }
                right--;
            }
        }
        final BigDecimal result = water;
        log.info(() -> "Trapped reserve = " + result);
        return water;
    }
}
