package com.bank.rainwater;

import java.math.BigDecimal;
import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

// Runnable demo: trapped reserve in Rajesh's balance skyline.
public class RainWaterDemo {
    private static final Logger log = Logger.getLogger(RainWaterDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    private static BigDecimal bd(String s) { return new BigDecimal(s); }

    public static void main(String[] args) {
        RainWaterAnalyzer analyzer = new RainWaterAnalyzer();

        // Rajesh (SAV2001) daily balances (in lakhs) as skyline bar heights.
        BigDecimal[] balances = { bd("0"), bd("1"), bd("0"), bd("2"), bd("1"),
                                  bd("0"), bd("1"), bd("3"), bd("2"), bd("1"),
                                  bd("2"), bd("1") };
        BigDecimal reserve = analyzer.trappedReserve(balances);
        log.info(() -> "Trapped reserve for Rajesh = " + reserve);
    }
}
